UPDATE TEACHER
dept = #{dept}, name = #{name}, professional_title = #{professionalTitle}, position = #{position}, birth = #{birth}, political = #{political}, phone = #{phone}, officePhone = #{officePhone}, password = #{password}, is_retired = #{isRetired}, is_full_time = #{isFullTime}, education = #{education}, staff_no = #{staffNo}, degree = #{degree},
WHERE teacher_id = #{teacherId}

mapper.select:
SELECT t.teacher_id, COALESCE(GROUP_CONCAT(d.dept_name), t.dept) AS dept, t.name, t.professional_title, t.position, t.birth, t.political, t.phone, t.officePhone, t.password, t.is_retired, t.is_full_time, t.education, t.staff_no, t.degree FROM TEACHER t LEFT JOIN TEACHER_DEPT td ON t.teacher_id = td.teacher_id LEFT JOIN DEPT d ON td.dept_id = d.dept_id
AND (t.teacher_id LIKE CONCAT('%', #{searchKey}, '%') OR t.name LIKE CONCAT('%', #{searchKey}, '%') OR t.phone LIKE CONCAT('%', #{searchKey}, '%'))
GROUP BY t.teacher_id ORDER BY t.teacher_id LIMIT #{offset}, #{pageSize}
